def solve(seed, D, avoid_occupied=False):
    out2=[row[:] for row in inp]
    def forward(r,c):
        path=[]
        while True:
            nr,nc=r+D[0],c+D[1]
            if not(0<=nr<H and 0<=nc<W): return path,(r,c)
            if inp[nr][nc]==8: return path,(r,c)
            r,c=nr,nc; path.append((r,c))
    def lateral(r,c):
        perp=[(0,-1),(0,1)] if D[0]!=0 else [(-1,0),(1,0)]
        for pd in perp:
            rr,cc=r,c
            while True:
                nr,nc=rr+pd[0],cc+pd[1]
                if not(0<=nr<H and 0<=nc<W): break
                fr,fc=nr+D[0],nc+D[1]
                turnable = 0<=fr<H and 0<=fc<W and inp[fr][fc]!=8
                if turnable and (not avoid_occupied or out2[fr][fc]!=2):
                    out2[nr][nc]=2; out2[fr][fc]=2
                    p,end=forward(fr,fc)
                    for cell in p: out2[cell[0]][cell[1]]=2
                    if inp[end[0]][end[1]]==0: lateral(*end)
                    break
                out2[nr][nc]=2
                rr,cc=nr,nc
    p,end=forward(*seed)
    for cell in p: out2[cell[0]][cell[1]]=2
    lateral(*end)
    return out2

